const stagedAttachments = `-- name: StagedAttachments :many
SELECT id, tenant_id, email_id, file_name, content_type, size_bytes, storage_key, created_by, created_at FROM email_attachment WHERE id = ANY($1::text[]) AND email_id IS NULL AND created_by = app_current_user()
`

// Files the user uploaded and has not sent yet, among ids.
func (q *Queries) StagedAttachments(ctx context.Context, ids []string) ([]EmailAttachment, error) {
	rows, err := q.db.Query(ctx, stagedAttachments, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []EmailAttachment
	for rows.Next() {
		var i EmailAttachment
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.EmailID,
			&i.FileName,
			&i.ContentType,
			&i.SizeBytes,
			&i.StorageKey,
			&i.CreatedBy,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateTemplate = `-- name: UpdateTemplate :one
UPDATE email_template SET name = $1, subject = $2, body = $3, body_html = $4,
  version = version + 1, updated_at = now()
WHERE id = $5 AND version = $6
RETURNING id, tenant_id, version, name, subject, body, created_by, created_at, updated_at, body_html
`

type UpdateTemplateParams struct {
	Name            string
	Subject         string
	Body            string
	BodyHtml        *string
	ID              string
	ExpectedVersion int32
}

// Optimistic concurrency: no row returned = stale version (or not found).
func (q *Queries) UpdateTemplate(ctx context.Context, arg UpdateTemplateParams) (EmailTemplate, error) {
	row := q.db.QueryRow(ctx, updateTemplate,
		arg.Name,
		arg.Subject,
		arg.Body,
		arg.BodyHtml,
		arg.ID,
		arg.ExpectedVersion,
	)
	var i EmailTemplate
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.Version,
		&i.Name,
		&i.Subject,
		&i.Body,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.BodyHtml,
	)
	return i, err
}
